sql.if:
and exists (
    select 1
    from purchase_group_member_scope group_scope
    where group_scope.purchase_group_id = #{criteria.scope.purchaseGroupId}
      and group_scope.purchase_org_id = f.purchase_org_id
      and group_scope.member_id = f.owner_id
      and group_scope.status = 1
      and (
        group_scope.effective_from is null
        or group_scope.effective_from <= #{criteria.businessDate}
      )
      and (
        group_scope.effective_to is null
        or group_scope.effective_to >= #{criteria.businessDate}
      )
)

mapper.select:
with metric_facts as (
) select f.group_code groupCode, f.metric_code metricCode, f.metric_name metricName, count(1) value, f.fact_source factSource, f.target_route targetRoute from metric_facts f where 1 = 1
group by f.group_code, f.metric_code, f.metric_name, f.fact_source, f.target_route order by f.group_code, f.metric_code

with todo_facts as (
) select f.todo_id todoId, f.business_type businessType, f.business_no businessNo, f.title, f.status_name statusName, f.priority, f.target_route targetRoute, f.purchase_org_id purchaseOrgId, f.owner_id ownerId, f.due_date dueDate, f.source_table sourceTable, f.source_id sourceId, f.created_at createdAt, f.updated_at updatedAt from todo_facts f where 1 = 1
order by
f.created_at f.due_date f.priority_rank f.updated_at
asc desc , f.todo_id asc limit #{criteria.offset}, #{criteria.pageSize}
